// One curated palette for the whole scene. Gradients step between its colors
// with ordered dithering instead of blending into mud, which keeps the retro
// look and keeps a frame well under the terminal's 1024 color pairs.

export const C = {
  ink: 0x0c0a14,
  black: 0x000000,
  white: 0xffffff,

  // Sky, calm night to storm to white-out.
  night0: 0x070818,
  night1: 0x0f1230,
  night2: 0x1b2150,
  night3: 0x2c3a78,
  storm0: 0x16081c,
  storm1: 0x3a0c2c,
  storm2: 0x6e1630,
  storm3: 0xa8282c,
  star: 0xdfe6ff,
  starDim: 0x6a76a8,

  // Mountains and ground.
  far0: 0x141838,
  far1: 0x1f2550,
  near0: 0x1a1426,
  near1: 0x2a1f36,
  soil0: 0x2a1c14,
  soil1: 0x3d2a1c,
  soil2: 0x5a3e26,
  soil3: 0x7c5734,
  crack: 0xffb347,

